<?php require __DIR__.'/lib/bootstrap.php';$user=require_auth();$days=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$w=db()->prepare('INSERT INTO working_hours(user_id,weekday,enabled,start_time,end_time) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),start_time=VALUES(start_time),end_time=VALUES(end_time)');for($i=0;$i<7;$i++)$w->execute([$user['id'],$i,isset($_POST['day'][$i])?1:0,$_POST['start'][$i]??'09:00',$_POST['end'][$i]??'19:00']);$q=db()->prepare('INSERT INTO preferences(user_id,whatsapp_notifications,daily_email,auto_confirm) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE whatsapp_notifications=VALUES(whatsapp_notifications),daily_email=VALUES(daily_email),auto_confirm=VALUES(auto_confirm)');$q->execute([$user['id'],isset($_POST['wpp'])?1:0,isset($_POST['email'])?1:0,isset($_POST['auto'])?1:0]);flash('Configurações salvas.');redirect('configuracoes.php');}$q=db()->prepare('SELECT * FROM working_hours WHERE user_id=?');$q->execute([$user['id']]);$hours=[];foreach($q->fetchAll() as $h)$hours[$h['weekday']]=$h;$q=db()->prepare('SELECT * FROM preferences WHERE user_id=?');$q->execute([$user['id']]);$prefs=$q->fetch()?:['whatsapp_notifications'=>1,'daily_email'=>0,'auto_confirm'=>1];require __DIR__.'/includes/shell-top.php';?>
<h1 class="h1">Configurações</h1><p class="muted">Horários de atendimento e preferências da conta.</p><div class="card" style="margin-top:20px;background:#352630;color:#fff;display:flex;justify-content:space-between;align-items:center;gap:12px"><div><b>Plano <?= $user['plan']==='premium'?'Premium':'Grátis' ?></b><p style="opacity:.7;margin:5px 0 0;font-size:12px">Conheça os recursos disponíveis.</p></div><a href="planos.php" class="btn">Ver planos</a></div><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><h2 style="font:800 21px 'Bricolage Grotesque';margin:28px 0 12px">Horários de atendimento</h2><div class="card"><?php foreach($days as $i=>$d):$h=$hours[$i]??['enabled'=>$i!==0,'start_time'=>'09:00:00','end_time'=>'19:00:00'];?><div class="list-row"><label class="grow"><input class="switch" type="checkbox" name="day[<?= $i ?>]" <?= $h['enabled']?'checked':'' ?>>　<b><?= $d ?></b></label><input type="time" name="start[<?= $i ?>]" value="<?= e(substr($h['start_time'],0,5)) ?>" style="padding:8px;border:1px solid var(--line);border-radius:10px"><input type="time" name="end[<?= $i ?>]" value="<?= e(substr($h['end_time'],0,5)) ?>" style="padding:8px;border:1px solid var(--line);border-radius:10px"></div><?php endforeach; ?></div><h2 style="font:800 21px 'Bricolage Grotesque';margin:28px 0 12px">Notificações</h2><div class="card"><?php foreach(['wpp'=>'Avisar novos agendamentos no WhatsApp','email'=>'Resumo diário por e-mail','auto'=>'Confirmar agendamentos automaticamente'] as $k=>$label):?><div class="list-row"><label class="grow"><b><?= $label ?></b></label><input class="switch" type="checkbox" name="<?= $k ?>" <?= $prefs[match($k){'wpp'=>'whatsapp_notifications','email'=>'daily_email','auto'=>'auto_confirm'}]?'checked':'' ?>></div><?php endforeach; ?></div><button class="btn" style="margin-top:20px">Salvar configurações</button></form>
<?php require __DIR__.'/includes/shell-bottom.php'; ?>
